/**
 * Golden-value parity tests for the ITM port (`./itm.ts`).
 *
 * `itm.fixture.json` is generated by `tools/parity/gen-itm-golden.py`, which
 * runs the original MeshCore-analytics Python implementation (gdal-trimmed)
 * over designed + seeded-random profiles. Every value here is asserted
 * against that Python output; the corpus-wide max |TS − Python| delta is
 * printed so it can be quoted in reports.
 */
import { describe, expect, it } from 'vitest';
import fixtureJson from './itm.fixture.json';
import {
  DEFAULT_USABLE_PATH_LOSS_DB,
  ITM_LAMBDA_M,
  ITM_LINK_LOS_MAX_V,
  ITM_NO_MAX_V,
  computeItmPathLoss,
  itmSignalBand,
  itmSignalThresholdsDb,
  sampleItmProfile,
  type ItmElevationSampler,
} from './itm.js';

/** Float noise allowance: identical equations in different languages. */
const TOLERANCE = 1e-9;

/**
 * rf-core's tsconfig deliberately has no DOM/node libs (portable WASM
 * reference package), so `console` is not in scope at type level; the vitest
 * runner still provides it at runtime. Used only to print the corpus delta.
 */
const runtimeConsole = (globalThis as { console?: { log: (message: string) => void } }).console;

type RawNumber = number | string;

interface RawGoldenResult {
  usable_threshold_db: number;
  path_loss_db: RawNumber;
  viable: boolean;
  max_v: RawNumber;
}

interface RawCase {
  name: string;
  kind: 'profile' | 'sampled';
  dists?: RawNumber[];
  heights?: RawNumber[];
  lat_a?: number;
  lon_a?: number;
  lat_b?: number;
  lon_b?: number;
  elevation_nodes?: Array<[number, number]>;
  h_tx: number;
  h_rx: number;
  results: RawGoldenResult[];
  sampled_dists?: RawNumber[];
  sampled_heights?: RawNumber[];
}

interface RawFixture {
  generator: string;
  reference: string;
  seed: number;
  tolerance_abs: number;
  thresholds_db: number[];
  cases: RawCase[];
}

const fixture = fixtureJson as unknown as RawFixture;

/** Fixture encodes non-finite numbers as strings (JSON has no such literals). */
function decodeNumber(value: RawNumber): number {
  if (typeof value === 'number') return value;
  if (value === 'NaN') return Number.NaN;
  if (value === 'Infinity') return Number.POSITIVE_INFINITY;
  if (value === '-Infinity') return Number.NEGATIVE_INFINITY;
  throw new Error(`unexpected non-finite encoding: ${value}`);
}

const decodeArray = (values: readonly RawNumber[]): number[] => values.map(decodeNumber);

/**
 * Piecewise-linear elevation in latitude — the same sampler the golden
 * generator used, built only from IEEE basic operations so heights come out
 * bit-identical.
 */
const nodeElevationSampler =
  (nodes: ReadonlyArray<readonly [number, number]>): ItmElevationSampler =>
  (lat: number): number => {
    const first = nodes[0]!;
    if (lat <= first[0]) return first[1];
    for (let i = 0; i < nodes.length - 1; i += 1) {
      const [la0, h0] = nodes[i]!;
      const [la1, h1] = nodes[i + 1]!;
      if (lat <= la1) return h0 + ((h1 - h0) * (lat - la0)) / (la1 - la0);
    }
    return nodes[nodes.length - 1]![1];
  };

/** Compare one fixture case against the Python golden values; return its max delta. */
function compareCase(c: RawCase): { delta: number; label: string } {
  let maxDelta = 0;
  let maxLabel = '(none)';

  const check = (label: string, actual: number, expected: number): void => {
    const delta =
      Number.isFinite(actual) && Number.isFinite(expected)
        ? Math.abs(actual - expected)
        : Object.is(actual, expected)
          ? 0
          : Number.POSITIVE_INFINITY;
    if (delta > maxDelta) {
      maxDelta = delta;
      maxLabel = label;
    }
    expect(delta, `${label}: TS ${actual} vs Python ${expected}`).toBeLessThanOrEqual(TOLERANCE);
  };

  let dists: number[];
  let heights: number[];
  if (c.kind === 'sampled') {
    const sampled = sampleItmProfile(
      { lat: c.lat_a!, lon: c.lon_a! },
      { lat: c.lat_b!, lon: c.lon_b! },
      nodeElevationSampler(c.elevation_nodes!),
    );
    const goldenDists = decodeArray(c.sampled_dists!);
    const goldenHeights = decodeArray(c.sampled_heights!);
    expect(sampled.dists.length).toBe(goldenDists.length);
    expect(sampled.heights.length).toBe(goldenHeights.length);
    for (let i = 0; i < goldenDists.length; i += 1) {
      check(`${c.name} sampled dists[${i}]`, sampled.dists[i]!, goldenDists[i]!);
    }
    for (let i = 0; i < goldenHeights.length; i += 1) {
      check(`${c.name} sampled heights[${i}]`, sampled.heights[i]!, goldenHeights[i]!);
    }
    dists = sampled.dists;
    heights = sampled.heights;
  } else {
    dists = decodeArray(c.dists!);
    heights = decodeArray(c.heights!);
  }

  for (const golden of c.results) {
    const out = computeItmPathLoss({
      dists,
      heights,
      hTxM: c.h_tx,
      hRxM: c.h_rx,
      usableThresholdDb: golden.usable_threshold_db,
    });
    expect(
      out.viable,
      `${c.name}: viable @ ${golden.usable_threshold_db} dB`,
    ).toBe(golden.viable);
    check(
      `${c.name} path_loss_db @ ${golden.usable_threshold_db}`,
      out.pathLossDb,
      decodeNumber(golden.path_loss_db),
    );
    check(
      `${c.name} max_v @ ${golden.usable_threshold_db}`,
      out.maxV,
      decodeNumber(golden.max_v),
    );
  }

  return { delta: maxDelta, label: maxLabel };
}

describe('itm fixture and constants', () => {
  it('fixture is loaded, well-formed and covers both thresholds', () => {
    expect(fixture.cases.length).toBeGreaterThanOrEqual(30);
    expect(fixture.thresholds_db).toContain(DEFAULT_USABLE_PATH_LOSS_DB);
    expect(fixture.thresholds_db).toContain(139.5);
    expect(fixture.tolerance_abs).toBe(TOLERANCE);
    for (const c of fixture.cases) {
      expect(c.results.length).toBe(2);
      expect(c.results.map((r) => r.usable_threshold_db)).toEqual(fixture.thresholds_db);
    }
  });

  it('corpus covers the required case families', () => {
    const names = fixture.cases.map((c) => c.name);
    const random = names.filter((n) => n.startsWith('rand-'));
    const sampled = fixture.cases.filter((c) => c.kind === 'sampled');
    expect(random.length).toBeGreaterThanOrEqual(8);
    expect(sampled.length).toBeGreaterThanOrEqual(4);
  });

  it('exports the reference constants', () => {
    expect(ITM_LAMBDA_M).toBeCloseTo(3e8 / 868e6, 15);
    expect(ITM_LINK_LOS_MAX_V).toBe(1.12);
    expect(DEFAULT_USABLE_PATH_LOSS_DB).toBe(137.5);
    expect(ITM_NO_MAX_V).toBe(-999);
  });
});

describe('itm golden parity (TS port vs reference Python)', () => {
  for (const c of fixture.cases) {
    it(`${c.name}`, () => {
      compareCase(c);
    });
  }

  it('corpus-wide max |TS − Python| stays within tolerance (printed for the record)', () => {
    let maxDelta = 0;
    let maxLabel = '(none)';
    let goldenResults = 0;
    for (const c of fixture.cases) {
      const outcome = compareCase(c);
      if (outcome.delta > maxDelta) {
        maxDelta = outcome.delta;
        maxLabel = outcome.label;
      }
      goldenResults += c.results.length;
    }
    runtimeConsole?.log(
      `[itm parity] ${fixture.cases.length} cases, ${goldenResults} golden model results; ` +
        `max |TS-Python| = ${maxDelta.toExponential(3)} at ${maxLabel}`,
    );
    expect(maxDelta).toBeLessThanOrEqual(TOLERANCE);
  });
});

describe('itm sampling convention', () => {
  const flat: ItmElevationSampler = () => 100;

  it('sample count follows max(20, min(200, floor(d/100))) with n+1 samples', () => {
    // ~10.0 km → n = 100 → 101 samples.
    const long = sampleItmProfile({ lat: 53, lon: -2 }, { lat: 53.09, lon: -2 }, flat);
    expect(long.dists.length).toBe(101);
    expect(long.dists[0]).toBe(0);
    expect(long.dists[100]!).toBeGreaterThan(10_000);
    expect(long.dists[100]!).toBeLessThan(10_100);
    expect(long.heights.every((h) => h === 100)).toBe(true);

    // ~1.0 km → floor(10) → clamped up to n = 20 → 21 samples.
    const short = sampleItmProfile({ lat: 53, lon: -2 }, { lat: 53.009, lon: -2 }, flat);
    expect(short.dists.length).toBe(21);
    expect(short.dists[20]!).toBeGreaterThan(999);
    expect(short.dists[20]!).toBeLessThan(1004);
  });

  it('heights are sanitised: out-of-range/non-finite → 0, negatives clamp to 0', () => {
    const pick: ItmElevationSampler = (lat) => {
      if (lat < 53.002) return -700; // below -500 → 0
      if (lat < 53.004) return 9500; // above 9000 → 0
      if (lat < 53.006) return -30; // negative but in range → clamped to 0
      if (lat < 53.008) return Number.NaN; // non-finite → 0
      return 2500; // valid, kept
    };
    const profile = sampleItmProfile({ lat: 53, lon: -2 }, { lat: 53.01, lon: -2 }, pick);
    expect(profile.heights.every((h) => h >= 0)).toBe(true);
    expect(profile.heights.filter((h) => h === 2500).length).toBeGreaterThanOrEqual(3);
    expect(profile.heights.filter((h) => h > 0 && h !== 2500).length).toBe(0);
  });

  it('sampled heights go through the single-point path for sub-metre endpoints', () => {
    const profile = sampleItmProfile({ lat: 53, lon: -2 }, { lat: 53.000002, lon: -2 }, () => -700);
    expect(profile.dists).toEqual([0]);
    expect(profile.heights).toEqual([0]);
    const kept = sampleItmProfile({ lat: 53, lon: -2 }, { lat: 53.000002, lon: -2 }, () => 250);
    expect(kept.dists).toEqual([0]);
    expect(kept.heights).toEqual([250]);
  });
});

describe('itm signal bands', () => {
  it('default thresholds are max(116, t−16) / max(124, t−8) / t', () => {
    expect(itmSignalThresholdsDb()).toEqual({ green: 121.5, amber: 129.5, red: 137.5 });
    expect(itmSignalThresholdsDb(139.5)).toEqual({ green: 123.5, amber: 131.5, red: 139.5 });
    // Lower thresholds can't drag green/amber below their floors.
    expect(itmSignalThresholdsDb(120)).toEqual({ green: 116, amber: 124, red: 120 });
  });

  it('classifies losses into green/amber/red with red as the catch-all band', () => {
    expect(itmSignalBand(120)).toBe('green');
    expect(itmSignalBand(121.5)).toBe('amber');
    expect(itmSignalBand(129.4)).toBe('amber');
    expect(itmSignalBand(129.5)).toBe('red');
    expect(itmSignalBand(150)).toBe('red');
    expect(itmSignalBand(120, 139.5)).toBe('green');
    expect(itmSignalBand(123.4, 139.5)).toBe('green');
    expect(itmSignalBand(123.5, 139.5)).toBe('amber');
  });
});
